<section class="page-section"><div class="container narrow"><div class="section-title"><div><p class="eyebrow"><?= e(__('LỊCH HOST')) ?></p><h1><?= e($listing['title']) ?></h1><p><?= e(__('Chặn hoặc mở một ngày chưa có booking xác nhận.')) ?></p></div><a class="btn btn-ghost" href="<?= e(url('/host')) ?>"><?= e(__('Quay lại')) ?></a></div><div class="surface-card"><form method="post" action="<?= e(url('/api/host/listings/'.$listing['id'].'/availability')) ?>"><div class="form-row align-items-end"><?= csrf_field() ?><div class="form-group col-md-4"><label for="date"><?= e(__('Ngày')) ?></label><input class="form-control" id="date" type="date" name="date" min="<?= date('Y-m-d') ?>" required></div><div class="form-group col-md-4"><label for="reason"><?= e(__('Lý do khi chặn')) ?></label><input class="form-control" id="reason" name="reason" placeholder="<?= e(__('Bảo trì / việc riêng')) ?>"></div><div class="form-group col-md-2"><button class="btn btn-outline-danger btn-block" name="open" value="0"><?= e(__('Chặn ngày')) ?></button></div><div class="form-group col-md-2"><button class="btn btn-primary btn-block" name="open" value="1"><?= e(__('Mở ngày')) ?></button></div></div></form><h2 class="mt-4"><?= e(__('Ngày đã thiết lập')) ?></h2><?php if(!$dates): ?><p class="text-muted"><?= e(__('Chưa có ngày chặn riêng. Các ngày mặc định đang mở nếu không có booking.')) ?></p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th><?= e(__('Ngày')) ?></th><th><?= e(__('Trạng thái')) ?></th><th><?= e(__('Lý do')) ?></th><th>Booking</th></tr></thead><tbody><?php foreach($dates as $date): ?><tr><td><?= e(display_date($date['stay_date'])) ?></td><td><span class="status <?= $date['is_open']?'status-approved':'status-rejected' ?>"><?= e($date['is_open']?__('Mở'):__('Đã chặn')) ?></span></td><td><?= e($date['block_reason']) ?></td><td><?= $date['booked']?e(__('Đã xác nhận')):'—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></section>
